      "anchors": [
        {
          "line_start": 105,
          "line_end": 107,
          "support": "A log plot of the number of trapped atoms as a function of hold time in both the 3D and 1D lattice is shown. Exponential decays are fitted, excluding data where t_hold < 75 ms."
        }
      ]
    }
  ],
  "fixed_conditions": [
    {
      "condition_id": "cond_3D_lattice",
      "statement": "3D lattice: single circularly-polarised laser beam, wavelength ~780 nm, power 0.9 W, e^-2 intensity radius 2.5 mm, red detuning 78 GHz from Rb D2 line, grating period 1080 nm, first-order diffraction angle 45 degrees, diffraction efficiencies eta_±1 ~35% and eta_0 ~5%.",
      "anchors": [
        {
          "line_start": 76,
          "line_end": 77,
          "support": "To make the 3D (1D) optical lattices, we use a single circularly- (linearly-) polarised laser beam, normally incident near the centre of the grating with wavelength ≈780 nm (1070 nm), power 0.9 W (10 W), and e^-2 intensity radius 2.5 mm (80 μm). For the near-resonant lattice at ≈780 nm, the laser red-detuning was 78 GHz relative to the center of the four Doppler-broadened D2 transitions. Due to the grating period d=1080 nm, the 780 nm light diffracts (±1-order) at an angle of θ=45° to the grating normal with diffraction efficiencies into the first and zeroth orders of η_±1≈35% and η_0≈5% respectively."
        }
      ]
    },
    {
      "condition_id": "cond_1D_lattice",
      "statement": "1D lattice: single linearly-polarised laser beam, wavelength ~1070 nm, power 10 W, e^-2 intensity radius 80 μm, far-off resonance, grating period 1080 nm, zeroth-order efficiency ~70%.",
      "anchors": [
        {
          "line_start": 76,
          "line_end": 77,
          "support": "To make the 3D (1D) optical lattices, we use a single circularly- (linearly-) polarised laser beam, normally incident near the centre of the grating with wavelength ≈780 nm (1070 nm), power 0.9 W (10 W), and e^-2 intensity radius 2.5 mm (80 μm). The 1070 nm light has most power in the zeroth order η_0≈70%."
        }
      ]
    },
    {
      "condition_id": "cond_common_experimental",
      "statement": "Base vacuum pressure at 10^-8 mbar level; atoms loaded from GMOT with ~8e6 87Rb atoms cooled to ~3 μK; stray DC magnetic fields cancelled by three pairs of orthogonal Helmholtz coils; fluorescence imaging with 150 μs resonant images after 1 ms time of flight following extinction of lattice beam.",
      "anchors": [
        {
          "line_start": 79,
          "line_end": 79,
          "support": "As a basis for loading the optical lattices, ≈8×10^6 87Rb atoms are loaded into a GMOT and cooled to ≈3 μK using a standard red molasses cooling stage. Stray DC magnetic fields are cancelled by three pairs of orthogonal Helmholtz coils."
        },
        {
          "line_start": 82,
          "line_end": 82,
          "support": "The grating chip is bonded to the open end facet of a rectangular cuvette vacuum cell using UHV compatible epoxy, allowing a base vacuum pressure at the 10^-8 mbar level."
        },
        {
          "line_start": 86,
          "line_end": 86,
          "support": "For both the 3D and 1D lattice geometries 150 μs long resonant fluorescent images are taken with the MOT light after a 1 ms time of flight following the extinction of the lattice beam."
        }
      ]
    }
